changeSet.sql:
DO $migration$ DECLARE expected RECORD; legacy RECORD; BEGIN -- A busy database must fail safely rather than wait indefinitely on the DDL lock. PERFORM set_config('lock_timeout', '5s', true); LOCK TABLE stock_reservation_item IN ACCESS EXCLUSIVE MODE;
-- Verify both replacement constraints, including columns and validation, -- before dropping anything. Names alone do not establish a correct FK. FOR expected IN SELECT * FROM (VALUES ('reservation_id', 'stock_reservations', 'stock_reservation'), ('stock_id', 'warehouse_stocks', 'warehouse_stock') ) AS mappings(column_name, target_table, legacy_table) LOOP IF NOT EXISTS ( SELECT 1 FROM pg_catalog.pg_constraint fk JOIN pg_catalog.pg_attribute source_column ON source_column.attrelid = fk.conrelid AND source_column.attname = expected.column_name JOIN pg_catalog.pg_attribute target_column ON target_column.attrelid = fk.confrelid AND target_column.attname = 'id' WHERE fk.contype = 'f' AND fk.convalidated AND fk.conrelid = 'stock_reservation_item'::regclass AND fk.confrelid = to_regclass(expected.target_table) AND fk.conkey = ARRAY[source_column.attnum] AND fk.confkey = ARRAY[target_column.attnum] ) THEN RAISE EXCEPTION 'Cannot remove legacy reservation foreign keys: validated FK %.% -> %(id) is missing', 'stock_reservation_item', expected.column_name, expected.target_table; END IF; END LOOP;
-- Match the legacy targets and columns instead of Hibernate-generated names. -- If already repaired manually (or on a new database), this loop is empty. FOR legacy IN SELECT fk.conname FROM pg_catalog.pg_constraint fk JOIN pg_catalog.pg_attribute source_column ON source_column.attrelid = fk.conrelid JOIN (VALUES ('reservation_id', 'stock_reservation'), ('stock_id', 'warehouse_stock') ) AS mappings(column_name, target_table) ON source_column.attname = mappings.column_name WHERE fk.contype = 'f' AND fk.conrelid = 'stock_reservation_item'::regclass AND fk.confrelid = to_regclass(mappings.target_table) AND fk.conkey = ARRAY[source_column.attnum] LOOP EXECUTE format('ALTER TABLE stock_reservation_item DROP CONSTRAINT %I', legacy.conname); END LOOP; END; $migration$;
